{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not nodes:
        raise ValueError("nodes is empty")
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Node {node!r} missing from core_distance")

    n = len(nodes)

    # Compute mutual reachability for each edge, canonicalizing endpoints
    mr_edges = []
    for edge in distances:
        u, v, dist = edge[0], edge[1], edge[2]
        # Canonicalize: lexicographic order
        if u > v:
            u, v = v, u
        if u not in core_distance or v not in core_distance:
            raise ValueError(f"Edge endpoint not in core_distance: {u!r}, {v!r}")
        mr = max(core_distance[u], core_distance[v], dist)
        mr_edges.append((mr, u, v))

    # Sort by mutual reachability weight, then by endpoint IDs for determinism
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find for Kruskal's algorithm
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; cannot form a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
